head = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b0b0d"><meta name="color-scheme" content="dark"><meta name="description" content="{description}"><title>{title} — Type Folio</title><link rel="icon" type="image/png" href="../favicon.png"><link rel="apple-touch-icon" href="../assets/apple-touch-icon.png"><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="../site-pages.css"><script src="../script.js" defer></script></head><body class="reading-page" id="top"><a class="skip-link" href="#main">Skip to content</a>'''

for slug, page in PAGES.items():
    toc=''.join(f'<a href="#{sid}">{title}</a>' for sid,title,_ in page['sections'])
    content=''.join(f'<section id="{sid}"><h2>{i}. {title}</h2>{body}</section>' for i,(sid,title,body) in enumerate(page['sections'],1))
    html=head.format(title=escape(page['title']),description=escape(page['intro'],quote=True))+header('../',slug)
    html+=f'''<main class="container reading-main" id="main"><div class="legal-intro"><p class="eyebrow">{page['eyebrow']}</p><h1>{page['title']}</h1><p>{page['intro']}</p><span class="legal-updated">Last updated <time datetime="2026-11-03">3 November 2026</time></span></div><div class="legal-layout"><nav class="legal-toc" aria-label="On this page"><span>ON THIS PAGE</span>{toc}</nav><article class="legal-content"><aside class="legal-highlight"><span aria-hidden="true">✦</span><p>{page['highlight']}</p></aside>{content}<div class="legal-endnote"><p>Still have a question?</p><a class="text-link" href="../contact/">Let’s talk <span aria-hidden="true">↗</span></a></div></article></div></main>'''
    html+=footer('../')+'</body></html>'
    (ROOT/slug).mkdir(exist_ok=True)
    (ROOT/slug/'index.html').write_text(html)

contact=head.format(title='Contact',description='Get help with Type Folio. Questions, feedback, account help, and purchase support.')+header('../','contact')+f'''
<main class="container reading-main" id="main"><div class="legal-intro"><p class="eyebrow">A LITTLE MISSION SUPPORT</p><h1>Let’s talk.</h1><p>A question, an unexpected detour, or an idea for your next orbit. We would love to hear it.</p></div>
<div class="contact-layout"><section class="contact-copy"><p class="eyebrow">BEFORE YOU WRITE</p><h2>Help us find <br>your coordinates.</h2><p>For a bug, include your device, app version, and the steps that led to the problem. If we need a screenshot, you can send it by email.</p><p>Never send passwords, sign-in codes, or full payment details.</p><div class="contact-quicklinks"><a href="../faq/">Find a quick answer <span aria-hidden="true">↗</span></a><a href="../purchases/">Purchase help <span aria-hidden="true">↗</span></a><a href="../delete-account/">Delete an account <span aria-hidden="true">↗</span></a></div></section>
{(ROOT/'tools'/'contact-form.html').read_text()}</div></main>'''+footer('../')+'</body></html>'
(ROOT/'contact').mkdir(exist_ok=True)
contact = contact.replace('</head>', '<script src="../contact.js" defer></script></head>')
(ROOT/'contact'/'index.html').write_text(contact)

# Recovery page uses an early blocking script to remove tokens from the URL.
reset_head = head.format(title='Reset your password', description='Choose a new password for your Type Folio account.').replace('href="../', 'href="/').replace('src="../', 'src="/')
reset_head = reset_head.replace('<meta name="description"', '<meta name="referrer" content="no-referrer"><meta name="robots" content="noindex, nofollow"><script src="/reset.js"></script><meta name="description"')
reset_head = reset_head.replace('</head>', '<link rel="stylesheet" href="/reset.css"><link rel="canonical" href="https://typefolioapp.nazrin.codes/reset"></head>')
(ROOT/'reset.html').write_text(reset_head + header('/') + (ROOT/'tools/reset-content.html').read_text() + footer('/') + '</body></html>')

# Keep the existing home content, replacing only shared chrome and the requested hero.
path=ROOT/'index.html'
home=path.read_text()
if 'site-pages.css' not in home:
    home=home.replace('<link rel="stylesheet" href="styles.css">','<link rel="stylesheet" href="styles.css">\n  <link rel="stylesheet" href="site-pages.css">')
if '<!-- shared-header -->' not in home:
    home=re.sub(r'<header class="site-header">.*?</header>', '<!-- shared-header -->'+header(home=True)+'<!-- /shared-header -->',home,flags=re.S)
else:
    home=re.sub(r'<!-- shared-header -->.*?<!-- /shared-header -->','<!-- shared-header -->'+header(home=True)+'<!-- /shared-header -->',home,flags=re.S)
